// Claude Code PreToolUse hook generated by agent-kit. It asks for (or denies) approval before a
// protected action, using the policy in .agent-kit/autonomy.json. Everything else passes through.
import { readFileSync, existsSync } from "node:fs";
import { join, relative, isAbsolute } from "node:path";
import { classifyCommand, classifyWrite } from "./policy.mjs";

function readStdin() {
  try {
    return JSON.parse(readFileSync(0, "utf8"));
  } catch {
    return null;
  }
}

function loadAutonomy(root) {
  const path = join(root, ".agent-kit", "autonomy.json");
  if (!existsSync(path)) return {};
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch {
    return {};
  }
}

function verdictFor(input, autonomy, root) {
  const tool = input.tool_name;
  const args = input.tool_input || {};
  if (tool === "Bash" || tool === "PowerShell") return classifyCommand(args.command, autonomy);
  if (["Write", "Edit", "MultiEdit", "NotebookEdit"].includes(tool)) {
    const target = args.file_path || args.notebook_path;
    if (!target) return { decision: "allow" };
    const path = isAbsolute(target) ? relative(root, target) : target;
    return classifyWrite(path, autonomy);
  }
  return { decision: "allow" };
}

const input = readStdin();
if (input) {
  const root = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
  const verdict = verdictFor(input, loadAutonomy(root), root);
  if (verdict.decision !== "allow") {
    process.stdout.write(
      JSON.stringify({
        hookSpecificOutput: {
          hookEventName: "PreToolUse",
          permissionDecision: verdict.decision,
          permissionDecisionReason: `agent-kit protected action (${verdict.category}): ${verdict.reason}. Needs explicit human approval.`,
        },
      })
    );
  }
}
